def solve():
    # Target grid (6x6)
    row_sums = [22, 36, 33, 33, 24, 28]
    col_sums = [27, 43, 34, 29, 22, 21]

    # Fixed values in the grid (0 means empty)
    grid = [
        [0, 7, 0, 1, 0, 0],
        [6, 0, 0, 0, 0, 2],
        [0, 0, 0, 8, 4, 0],
        [0, 0, 6, 0, 0, 0],
        [0, 0, 3, 0, 2, 0],
        [0, 0, 4, 0, 2, 0]
    ]

    # The multiset of numbers to use for the '0' cells
    available_nums = [6, 7, 8, 3, 5, 6, 5, 9, 4, 4, 9, 2, 8, 5, 7, 3, 3, 1, 6, 6, 6, 8, 3, 5, 2]
    counts = Counter(available_nums)

    empty_cells = []
    for r in range(6):
        for c in range(6):
            if grid[r][c] == 0:
                empty_cells.append((r, c))

    def backtrack(idx):
        if idx == len(empty_cells):
            # Check all column sums at the very end
            for c in range(6):
                if sum(grid[r][c] for r in range(6)) != col_sums[c]:
                    return False
            return True

        r, c = empty_cells[idx]

        # Which empty cells are left in this row and column?
        row_remaining_count = sum(1 for i in range(idx + 1, len(empty_cells)) if empty_cells[i][0] == r)
        col_remaining_count = sum(1 for i in range(idx + 1, len(empty_cells)) if empty_cells[i][1] == c)

        # Try numbers from the counter
        for num in sorted(counts.keys()):
            if counts[num] > 0:
                # Check row sum constraint
                curr_row_sum = sum(grid[r][j] for j in range(6) if grid[r][j] != 0) + num
                if row_remaining_count == 0:
                    if curr_row_sum != row_sums[r]: continue
                else:
                    if curr_row_sum >= row_sums[r]: continue

                # Check col sum constraint
                curr_col_sum = sum(grid[i][c] for i in range(6) if grid[i][c] != 0) + num
                if col_remaining_count == 0:
                    if curr_col_sum != col_sums[c]: continue
                else:
                    if curr_col_sum >= col_sums[c]: continue

                # Apply
                grid[r][c] = num
                counts[num] -= 1

                if backtrack(idx + 1):
                    return True

                # Backtrack
                counts[num] += 1
                grid[r][c] = 0
        return False

    if backtrack(0):
        return grid
    return None

